using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
namespace NoiteSemFim {
public sealed partial class SurvivorGame {
 bool AttackRelicFor(int character,int talisman)=>character==3&&talisman==1||character==4&&talisman==5||character==5&&talisman==7;
 bool HasAttackRelic=>AttackRelicFor(WeaponArchetype,runTalisman);
 bool HasLabAttackRelic=>AttackRelicFor(WeaponArchetype,labTalisman);
 string AttackRelicDescription(int character)=>character==3?"Olho Espinhoso: a katana também lança cortes à distância.":character==4?"Medalhão do Dragão: o espadão abre fissuras em linha.":character==5?"Estrela do Amanhecer: cada impacto divide a flecha em duas.":"";
 sealed class RelicFissure {public SpriteRenderer sprite;public Vector2 origin,direction;public float age,damage,area;public int next;public readonly HashSet<Enemy> hit=new HashSet<Enemy>();}
 readonly List<RelicFissure> relicFissures=new List<RelicFissure>();
 void ResetRelicAttacks(){foreach(var f in relicFissures)if(f.sprite!=null)Dispose(f.sprite.gameObject);relicFissures.Clear();}
 void ReleaseAttackRelic(Vector2 aim,int rank){if(!HasAttackRelic)return;if(WeaponArchetype==3){int before=shots.Count;Fire(pos,aim*10,(11+rank*4)*Power*.7f*(evolved[1]?1.8f:1),.28f*Area,3,new Color(.8f,.5f,1),1.2f,1);if(shots.Count>before){var s=shots[shots.Count-1];s.relicFxRow=0;s.sprite.sprite=ArtBank.AttackRelicFx(0);s.sprite.color=Color.white;s.sprite.transform.localScale=Vector3.one*1.8f*Area;}}
  else if(WeaponArchetype==4&&relicFissures.Count<24){var f=new RelicFissure{origin=pos,direction=aim,damage=(20+rank*5)*Power*(evolved[1]?1.8f:1),area=Area};f.sprite=Sprite("Fissura do espadão",ArtBank.AttackRelicFx(1),pos+aim*3,6*Area,Color.white,-195);f.sprite.transform.rotation=Quaternion.Euler(0,0,Mathf.Atan2(aim.y,aim.x)*Mathf.Rad2Deg);relicFissures.Add(f);}}
 void UpdateRelicFissures(float dt){for(int i=relicFissures.Count-1;i>=0;i--){var f=relicFissures[i];f.age+=dt;if(f.age>=1.15f){if(f.sprite!=null)Dispose(f.sprite.gameObject);relicFissures.RemoveAt(i);continue;}f.sprite.sprite=ArtBank.AttackRelicFx(1,Mathf.Min(3,(int)(f.age/1.15f*4)));f.sprite.color=new Color(1,1,1,Mathf.Clamp01((1.15f-f.age)*4));while(f.next<7&&f.age>=.1f+f.next*.08f){Vector2 center=f.origin+f.direction*(.5f+f.next*.8f)*f.area;f.next++;foreach(var e in enemies.ToArray()){if(f.hit.Contains(e)||!enemies.Contains(e)||Vector2.Distance(e.p,center)>(.7f+(IsBoss(e.type)?.65f:.15f))*f.area)continue;f.hit.Add(e);BurnEnemy(e,2,3*Power);Damage(e,f.damage);if(state!=ScreenState.Playing)return;}}}}
 void SplitRelicArrow(Shot parent){if(!parent.lunarArrow||parent.relicFxRow!=2)return;for(int side=-1;side<=1;side+=2){Vector2 direction=Rotate(parent.v.normalized,side*.38f);int before=shots.Count;Fire(parent.p+direction*.22f,direction*11,parent.damage*.45f,parent.radius*.85f,1,new Color(.55f,.9f,1),.8f,0);if(shots.Count<=before)continue;var child=shots[shots.Count-1];child.lunarArrow=true;child.relicFxRow=2;child.splitOnHit=false;child.hit.UnionWith(parent.hit);child.sprite.sprite=ArtBank.AttackRelicFx(2);child.sprite.color=Color.white;child.sprite.transform.localScale=Vector3.one*.85f;}}
 void SyncRelicAttackPixels(){foreach(var f in relicFissures){var p=Pixel(f.sprite,f.sprite.transform.position,6*f.area,.09f,true,false,6);if(p!=null)p.view.transform.rotation=Quaternion.Euler(90,0,-Mathf.Atan2(f.direction.y,f.direction.x)*Mathf.Rad2Deg);}}
 string VerifyRelicAttacks(){var account=save;int oldHero=heroIndex,pet=selectedDragon,curse=selectedCurse;bool previous=verifying,aim=manualAim;verifying=true;save=new SaveData{rescuedHeroes=63,relicOwned=255};selectedDragon=selectedCurse=-1;manualAim=false;
  for(int h=3;h<6;h++){heroIndex=h;int talisman=h==3?1:h==4?5:7;if(!TryEquipRelic(h,talisman))throw new Exception("Attack relic cannot equip");StartRun();var target=SpawnEnemy(0,false);target.p=Vector2.right*5;target.hp=target.maxHp=10000;if(!HasAttackRelic||!CanPreparePower(StartingWeapon))throw new Exception("Attack relic range not active");if(h==3){ReleasePower(1,1);if(shots.Count!=1||shots[0].relicFxRow!=0)throw new Exception("Katana ranged slash missing");float hp0=target.hp;for(int i=0;i<55;i++)UpdateShots(.01f);if(target.hp>=hp0)throw new Exception("Ranged slash did not hit distant target");}if(h==4){ReleasePower(1,1);if(relicFissures.Count!=1||target.hp!=10000)throw new Exception("Fissure missing or damage has no travel delay");UpdateShots(.09f);if(target.hp!=10000)throw new Exception("Fissure skips propagation");for(int i=0;i<80;i++)UpdateShots(.01f);if(target.hp>=10000||relicFissures[0].hit.Count!=1)throw new Exception("Fissure did not reach target");float after=target.hp;UpdateRelicFissures(.1f);if(target.hp!=after)throw new Exception("Fissure hits same enemy every frame");UpdateRelicFissures(1);if(relicFissures.Count!=0)throw new Exception("Fissure visual did not retire");}if(h==5){target.p=Vector2.right*1.3f;ReleasePower(0,1);if(shots.Count!=1||!shots[0].splitOnHit)throw new Exception("Lunar split parent missing");var parent=shots[0];for(int i=0;i<10;i++)UpdateShots(.01f);if(shots.Count!=3||parent.hit.Count!=1)throw new Exception("Arrow did not produce exactly two children");foreach(var shot in shots)if(shot!=parent&&(shot.splitOnHit||!shot.hit.Contains(target)))throw new Exception("Split arrows recurse or re-hit original target");var other=SpawnEnemy(0,false);var child=shots.Find(s=>s!=parent);other.p=child.p+child.v.normalized*.3f;other.hp=10000;for(int i=0;i<6;i++)UpdateShots(.01f);if(other.hp>=10000)throw new Exception("Split child does not deal damage");if(shots.Exists(s=>s!=parent&&s.splitOnHit))throw new Exception("Split recursion escaped cap");}
   UnequipRelic(h,1);StartRun();if(HasAttackRelic||relicFissures.Count>0)throw new Exception("Unequip retained attack mutation");ReleasePower(StartingWeapon,1);if(h==3&&shots.Count!=0||h==4&&relicFissures.Count!=0||h==5&&shots.Exists(s=>s.splitOnHit))throw new Exception("Base attack still modified after unequip");}
  heroIndex=4;TryEquipRelic(4,5);StartFinal3DDemo();AdvanceFinalTransition(4);ReleasePower(1,1);UpdateRelicFissures(.3f);FinalCamera();SyncPixelFinal();if(relicFissures.Count!=1||!pixelFinal.TryGetValue(relicFissures[0].sprite,out var visual)||Vector3.Dot(visual.view.transform.forward,Vector3.up)>-.99f)throw new Exception("Fissure is not projected onto 2.5D ground");for(int row=0;row<3;row++)for(int frame=0;frame<4;frame++)if(ArtBank.AttackRelicFx(row,frame)==null)throw new Exception("Relic animation frame missing");save=account;heroIndex=oldHero;selectedDragon=pet;selectedCurse=curse;manualAim=aim;verifying=previous;ReturnMenu();return "Attack relics PASS: boss talisman equip/range, animated katana projectile and distant hit, fissure propagation/one hit/lifetime, arrow piercing/two nonrecursive damaging children, original-target exclusion, unequip/reset, 12 VFX poses and 2.5D floor projection.";
 }
 IEnumerator CaptureRelicAttacks(string folder){verifying=true;Application.runInBackground=true;System.IO.Directory.CreateDirectory(folder);save=new SaveData{rescuedHeroes=63,relicOwned=255};selectedDragon=selectedCurse=-1;manualAim=false;foreach(int h in new[]{3,4,5}){heroIndex=h;TryEquipRelic(h,h==3?1:h==4?5:7);StartRun();elementPreviewFrozen=true;for(int i=0;i<5;i++){var e=SpawnEnemy(0,false);e.p=new Vector2(i==0?1.3f:3+i*.5f,i==0?0:(i%2==0?.7f:-.7f));e.hp=10000;e.sprite.transform.position=e.p;}ReleasePower(StartingWeapon,4);for(int i=0;i<(h==3?25:h==4?30:13);i++)UpdateShots(.01f);AnimateHero(.01f,Vector2.zero);toastUntil=0;yield return Capture(folder,"reliquia-heroi-"+h+"-2d-v23");elementPreviewFrozen=false;StartFinal3DDemo();AdvanceFinalTransition(4);elementPreviewFrozen=true;finalBoss.p=pos+Vector2.right*5;finalBoss.sprite.transform.position=finalBoss.p;ReleasePower(StartingWeapon,4);for(int i=0;i<25;i++)UpdateShots(.01f);AnimateHero(.01f,Vector2.zero);FinalCamera();SyncPixelFinal();toastUntil=0;yield return Capture(folder,"reliquia-heroi-"+h+"-25d-v23");elementPreviewFrozen=false;ReturnMenu();}heroIndex=3;EnterBuildLab();labTalisman=1;yield return Capture(folder,"reliquia-treino-v23");ReturnMenu();Debug.Log("ATTACK RELICS CAPTURE PASS");Application.Quit();}
}
}
